import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../static/css/cryptoList.css';

const CryptoList = () => {
    const [cryptos, setCryptos] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        axios.get('http://localhost:8080/api/cryptocurrencies')
            .then(response => setCryptos(response.data))
            .catch(error => console.error('Error fetching cryptos:', error));
    }, []);

    const handleRowClick = (id) => {
        navigate(`/cryptocurrencies/${id}`);
    };

    return (
        <div className="crypto-list-container">
            <h1 className="title">Liste des Cryptomonnaies</h1>
            <table className="crypto-table">
                <thead>
                <tr>
                    <th>Rang</th>
                    <th>Nom</th>
                    <th>Symbole</th>
                    <th>Prix</th>
                </tr>
                </thead>
                <tbody>
                {cryptos.map((crypto) => (
                    <tr key={crypto.id} onClick={() => handleRowClick(crypto.id)} className="crypto-row">
                        <td>{crypto.rank}</td>
                        <td>{crypto.name}</td>
                        <td>{crypto.symbol}</td>
                        <td>{crypto.price.toFixed(2)} $</td>
                    </tr>
                ))}
                </tbody>
            </table>
        </div>
    );
};

export default CryptoList;
